import{_ as a,c as l,o as t,ag as r}from"./chunks/framework.DPDPlp3K.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wechat/old/域名、子域名、IP地址与服务器端口之间的关系以及子域名和反向代理的区别.wechat.md","filePath":"wechat/old/域名、子域名、IP地址与服务器端口之间的关系以及子域名和反向代理的区别.wechat.md"}'),e={name:"wechat/old/域名、子域名、IP地址与服务器端口之间的关系以及子域名和反向代理的区别.wechat.md"};function i(n,o,s,h,g,d){return t(),l("div",null,o[0]||(o[0]=[r('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>网络基础补课：域名、子域名、IP、端口和反向代理一次讲清楚</li><li>别再混淆了！一篇搞懂域名、端口、服务器和反向代理</li><li>部署网站前必看：域名解析和反向代理到底是什么关系？</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合准备部署网站或服务的同学，讲清域名、子域名、IP、端口和反向代理的关系，帮你理解访问链路。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>部署网站时很多问题不是代码问题，而是访问链路没理清。</strong></p><p>域名、子域名、IP、端口、反向代理这些概念经常一起出现，如果边界不清楚，排查问题会非常绕。</p><p>这篇我们用更直白的方式，把它们之间的关系拆开讲清楚。</p><h2 id="知识点整理" tabindex="-1">知识点整理 <a class="header-anchor" href="#知识点整理" aria-label="Permalink to &quot;知识点整理&quot;">​</a></h2><p>下面进入概念整理。建议把一次真实访问拆成“用户输入域名 -&gt; 解析到 IP -&gt; 访问端口 -&gt; 反向代理转发”这条线来看。</p><p>如果你正在配置网站访问，可以把自己的域名解析、服务器端口和代理规则画成一条链路，会更容易定位问题。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>在互联网架构中，域名、子域名、IP地址与服务器端口共同构成了网站和服务的访问路径。理解它们之间的关系，有助于更好地管理和部署网络服务。</p><h2 id="_1-域名" tabindex="-1">1. 域名 <a class="header-anchor" href="#_1-域名" aria-label="Permalink to &quot;1. 域名&quot;">​</a></h2><ul><li><strong>定义</strong>：域名是一个人类可读的地址，用于识别互联网上的网站，例如 <code>example.com</code>。</li><li><strong>功能</strong>： <ul><li><strong>识别网站</strong>：帮助用户轻松记忆和访问网站。</li><li><strong>DNS解析</strong>：通过域名系统（DNS）将域名解析为对应的IP地址，便于计算机定位和访问网站。</li></ul></li></ul><h2 id="_2-子域名" tabindex="-1">2. 子域名 <a class="header-anchor" href="#_2-子域名" aria-label="Permalink to &quot;2. 子域名&quot;">​</a></h2><ul><li><strong>定义</strong>：子域名是主域名的扩展部分，用于组织或分类网站的不同部分，例如 <code>blog.example.com</code> 或 <code>shop.example.com</code>。</li><li><strong>功能</strong>： <ul><li><strong>服务分类</strong>：将不同的服务或功能模块区分开，例如博客、商店、API等。</li><li><strong>灵活部署</strong>：可以指向与主域名相同的服务器，也可以配置指向不同的服务器，实现服务的分离和独立管理。</li><li><strong>更高层级的域名</strong>：（三级或者四级域名 <code>extra.sub.blog.example.com</code>）也是可行的，主要用于进一步的组织和分类</li></ul></li></ul><h2 id="_3-ip地址" tabindex="-1">3. IP地址 <a class="header-anchor" href="#_3-ip地址" aria-label="Permalink to &quot;3. IP地址&quot;">​</a></h2><ul><li><strong>定义</strong>：IP地址（如 <code>192.168.1.1</code> 或 <code>2001:0db8:85a3:0000:0000:8a2e:0370:7334</code>）是分配给网络上每个设备的数字标签。</li><li><strong>功能</strong>： <ul><li><strong>设备识别</strong>：用于唯一标识网络中的每个设备。</li><li><strong>数据传输</strong>：指导数据在互联网上的传输路径，确保数据准确到达目标设备。</li></ul></li></ul><h2 id="_4-服务器端口" tabindex="-1">4. 服务器端口 <a class="header-anchor" href="#_4-服务器端口" aria-label="Permalink to &quot;4. 服务器端口&quot;">​</a></h2><ul><li><strong>定义</strong>：端口是服务器上用于通信的逻辑端点，每个端口号对应一个特定的服务。</li><li><strong>常用端口</strong>： <ul><li><strong>端口 80</strong>：HTTP（网页服务）</li><li><strong>端口 443</strong>：HTTPS（加密网页服务）</li><li><strong>端口 22</strong>：SSH（安全远程访问）</li><li><strong>端口 25</strong>：SMTP（电子邮件发送）</li></ul></li><li><strong>功能</strong>： <ul><li><strong>服务区分</strong>：通过不同的端口号，服务器可以同时运行多个服务而互不干扰。</li><li><strong>访问控制</strong>：控制不同服务的访问权限和安全性。</li></ul></li></ul><h2 id="_5-它们如何协同工作" tabindex="-1">5. 它们如何协同工作 <a class="header-anchor" href="#_5-它们如何协同工作" aria-label="Permalink to &quot;5. 它们如何协同工作&quot;">​</a></h2><p>当用户在浏览器中输入 <code>www.example.com</code> 时，以下过程发生：</p><ol><li><strong>DNS查询</strong>：浏览器通过DNS查询，将 <code>www.example.com</code> 解析为对应的IP地址。</li><li><strong>连接端口</strong>：浏览器连接到该IP地址上的相关端口（例如端口80用于HTTP）。</li><li><strong>服务响应</strong>：服务器监听该端口，并提供请求的服务（如网页内容）。</li></ol><p><strong>子域名的作用</strong>：</p><ul><li>可以将流量引导到不同的IP地址或端口，实现同一域名下不同服务的分离和独立管理。</li></ul><h2 id="_6-反向代理与子域名的区别" tabindex="-1">6. 反向代理与子域名的区别 <a class="header-anchor" href="#_6-反向代理与子域名的区别" aria-label="Permalink to &quot;6. 反向代理与子域名的区别&quot;">​</a></h2><h3 id="相似之处" tabindex="-1">相似之处 <a class="header-anchor" href="#相似之处" aria-label="Permalink to &quot;相似之处&quot;">​</a></h3><ul><li><strong>服务分离</strong>：二者都可以实现不同服务之间的分离。</li><li><strong>流量分发</strong>：都能将流量分发到不同的服务器或服务。</li></ul><h3 id="不同之处" tabindex="-1">不同之处 <a class="header-anchor" href="#不同之处" aria-label="Permalink to &quot;不同之处&quot;">​</a></h3><ul><li><strong>分发机制</strong>： <ul><li><strong>反向代理</strong>：基于URL路由（如路径或查询参数）来区分服务。例如，<code>/api/</code> 路径的请求转发到API服务器，<code>/static/</code> 转发到静态资源服务器。</li><li><strong>子域名</strong>：基于不同的域名来区分服务。例如，<code>api.example.com</code> 和 <code>www.example.com</code> 分别指向不同的服务器或服务。</li></ul></li><li><strong>配置层级</strong>： <ul><li><strong>反向代理</strong>：在服务器配置层面进行设置，需要配置代理服务器（如Nginx、HAProxy等）。</li><li><strong>子域名</strong>：在DNS配置层面进行设置，通过DNS记录将不同域名指向不同的IP地址或服务器。</li></ul></li></ul><h3 id="实际应用场景" tabindex="-1">实际应用场景 <a class="header-anchor" href="#实际应用场景" aria-label="Permalink to &quot;实际应用场景&quot;">​</a></h3><ul><li><strong>反向代理</strong>： <ul><li>适用于在同一域名下提供多种服务，尤其需要隐藏服务器架构或进行流量分配时。</li><li>常用于微服务架构，通过路径路由将请求分发到不同的服务。</li></ul></li><li><strong>子域名</strong>： <ul><li>适用于区分完全不同的服务或应用，尤其希望为每个服务提供独立的域名时。</li><li>常用于大型网站，将不同功能模块（如博客、商店、论坛）分配到不同的二级域名。</li></ul></li></ul><h2 id="_7-总结" tabindex="-1">7. 总结 <a class="header-anchor" href="#_7-总结" aria-label="Permalink to &quot;7. 总结&quot;">​</a></h2><p>域名、子域名、IP地址与服务器端口共同构建了互联网服务的访问架构。理解它们之间的关系和区别，有助于更高效地设计和管理网络服务。反向代理和二级域名虽然在服务分离和流量分发上有相似之处，但它们在实现机制和适用场景上有所不同。根据具体需求选择合适的方法，可以优化服务性能和管理效率。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你部署网站时最容易混淆的是域名解析、端口开放，还是反向代理规则？可以把你的访问链路留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>网络、编程相关、网络基础、域名解析、反向代理</p>',48)]))}const _=a(e,[["render",i]]);export{u as __pageData,_ as default};
